create type public.app_role as enum ('super_admin','admin1','admin2','admin_packing');
create type public.ledger as enum ('admin1','admin2');
create type public.tx_type as enum ('income','expense','transfer_in','transfer_out');
create type public.review_status as enum ('unchecked','match','mismatch');
create type public.pl_status as enum ('draft','siap_dimuat','dimuat','berlayar','tiba','selesai','dibatalkan');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null default '',email text not null default '',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
grant select,update on public.profiles to authenticated;grant all on public.profiles to service_role;alter table public.profiles enable row level security;
create table public.user_roles(id uuid primary key default gen_random_uuid(),user_id uuid not null unique references auth.users(id) on delete cascade,role public.app_role not null,disabled_at timestamptz,created_at timestamptz not null default now());
grant select on public.user_roles to authenticated;grant all on public.user_roles to service_role;alter table public.user_roles enable row level security;
create unique index unique_ledger_role on public.user_roles(role) where role in ('admin1','admin2');
create function public.has_role(_user_id uuid,_role public.app_role) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.user_roles where user_id=_user_id and role=_role and disabled_at is null)$$;
create function public.current_ledger() returns public.ledger language sql stable security definer set search_path=public as $$select case role when 'admin1' then 'admin1'::public.ledger when 'admin2' then 'admin2'::public.ledger end from public.user_roles where user_id=auth.uid() and disabled_at is null$$;
create function public.is_staff() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.user_roles where user_id=auth.uid() and role in ('super_admin','admin_packing') and disabled_at is null)$$;
revoke all on function public.has_role(uuid,public.app_role),public.current_ledger(),public.is_staff() from public,anon;grant execute on function public.has_role(uuid,public.app_role),public.current_ledger(),public.is_staff() to authenticated,service_role;
create policy "own profile or super admin" on public.profiles for select to authenticated using(id=auth.uid() or public.has_role(auth.uid(),'super_admin'));
create policy "update own profile" on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
create policy "own role or super admin" on public.user_roles for select to authenticated using(user_id=auth.uid() or public.has_role(auth.uid(),'super_admin'));
create function public.update_updated_at() returns trigger language plpgsql set search_path=public as $$begin new.updated_at=now();return new;end$$;
create trigger trg_profiles_upd before update on public.profiles for each row execute function public.update_updated_at();
create function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$begin insert into public.profiles(id,full_name,email) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',''),coalesce(new.email,'')) on conflict(id) do nothing;return new;end$$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
create table public.bank_accounts(id uuid primary key default gen_random_uuid(),ledger public.ledger not null,name text not null check(char_length(name) between 1 and 50),opening_balance numeric(18,2) not null default 0,sort_order int not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(ledger,name));
grant select,insert,update on public.bank_accounts to authenticated;grant all on public.bank_accounts to service_role;alter table public.bank_accounts enable row level security;
create policy "read accounts" on public.bank_accounts for select to authenticated using(public.has_role(auth.uid(),'super_admin') or ledger=public.current_ledger());
create policy "super insert accounts" on public.bank_accounts for insert to authenticated with check(public.has_role(auth.uid(),'super_admin'));
create policy "super update accounts" on public.bank_accounts for update to authenticated using(public.has_role(auth.uid(),'super_admin')) with check(public.has_role(auth.uid(),'super_admin'));
create trigger trg_accounts_upd before update on public.bank_accounts for each row execute function public.update_updated_at();
create table public.import_batches(id uuid primary key default gen_random_uuid(),ledger public.ledger not null,file_name text not null,rows_total int not null default 0,rows_imported int not null default 0,rows_skipped int not null default 0,status text not null default 'completed',created_by uuid not null default auth.uid(),created_at timestamptz not null default now());
grant select,insert on public.import_batches to authenticated;grant all on public.import_batches to service_role;alter table public.import_batches enable row level security;
create policy "read imports" on public.import_batches for select to authenticated using(public.has_role(auth.uid(),'super_admin') or ledger=public.current_ledger());
create policy "insert own imports" on public.import_batches for insert to authenticated with check(ledger=public.current_ledger() and created_by=auth.uid());
create table public.transactions(id uuid primary key default gen_random_uuid(),ledger public.ledger not null,account_id uuid not null references public.bank_accounts(id),tx_date date not null,description text not null check(char_length(description) between 1 and 200),tx_type public.tx_type not null,amount numeric(18,2) not null check(amount>0 and amount<1000000000000),category text check(category is null or char_length(category)<=50),transfer_id uuid,import_id uuid references public.import_batches(id),fingerprint text,client_ref uuid unique,created_by uuid not null default auth.uid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),review_status public.review_status not null default 'unchecked',reviewed_by uuid,reviewed_at timestamptz);
grant select,insert on public.transactions to authenticated;grant all on public.transactions to service_role;alter table public.transactions enable row level security;
create index idx_tx_ledger_date on public.transactions(ledger,tx_date desc);create index idx_tx_account on public.transactions(account_id);create index idx_tx_transfer on public.transactions(transfer_id);create index idx_tx_import on public.transactions(import_id);create unique index uq_tx_fingerprint on public.transactions(ledger,fingerprint) where fingerprint is not null;
create policy "read transactions" on public.transactions for select to authenticated using(public.has_role(auth.uid(),'super_admin') or ledger=public.current_ledger());
create policy "admins insert own ledger" on public.transactions for insert to authenticated with check(ledger=public.current_ledger() and created_by=auth.uid() and tx_type in ('income','expense') and transfer_id is null);
create function public.validate_transaction() returns trigger language plpgsql set search_path=public as $$declare acc_ledger public.ledger;begin select ledger into acc_ledger from public.bank_accounts where id=new.account_id;if acc_ledger is null or acc_ledger<>new.ledger then raise exception 'Rekening tidak sesuai dengan pembukuan';end if;if new.tx_date>current_date+1 or new.tx_date<date '2000-01-01' then raise exception 'Tanggal transaksi tidak valid';end if;return new;end$$;
create trigger trg_tx_validate before insert or update on public.transactions for each row execute function public.validate_transaction();create trigger trg_tx_upd before update on public.transactions for each row execute function public.update_updated_at();
create table public.audit_logs(id uuid primary key default gen_random_uuid(),transaction_id uuid,ledger public.ledger,actor_id uuid not null,action text not null,before_data jsonb,after_data jsonb,reason text,result text not null default 'success',created_at timestamptz not null default now());
grant select on public.audit_logs to authenticated;grant all on public.audit_logs to service_role;alter table public.audit_logs enable row level security;create index idx_audit_created on public.audit_logs(created_at desc);create policy "super admin reads audit" on public.audit_logs for select to authenticated using(public.has_role(auth.uid(),'super_admin'));
create table public.reconciliations(id uuid primary key default gen_random_uuid(),account_name text not null,as_of date not null,balance_admin1 numeric(18,2) not null,balance_admin2 numeric(18,2) not null,difference numeric(18,2) not null,notes text check(notes is null or char_length(notes)<=500),created_by uuid not null default auth.uid(),created_at timestamptz not null default now());
grant select,insert on public.reconciliations to authenticated;grant all on public.reconciliations to service_role;alter table public.reconciliations enable row level security;
create policy "super admin reads recon" on public.reconciliations for select to authenticated using(public.has_role(auth.uid(),'super_admin'));create policy "super admin inserts recon" on public.reconciliations for insert to authenticated with check(public.has_role(auth.uid(),'super_admin') and created_by=auth.uid());
create view public.account_balances with(security_invoker=true) as select a.id as account_id,a.ledger,a.name,a.sort_order,a.opening_balance,coalesce(sum(t.amount) filter(where t.tx_type='income'),0)::numeric(18,2) as income,coalesce(sum(t.amount) filter(where t.tx_type='expense'),0)::numeric(18,2) as expense,coalesce(sum(t.amount) filter(where t.tx_type='transfer_in'),0)::numeric(18,2) as transfer_in,coalesce(sum(t.amount) filter(where t.tx_type='transfer_out'),0)::numeric(18,2) as transfer_out,(a.opening_balance+coalesce(sum(t.amount) filter(where t.tx_type in ('income','transfer_in')),0)-coalesce(sum(t.amount) filter(where t.tx_type in ('expense','transfer_out')),0))::numeric(18,2) as balance from public.bank_accounts a left join public.transactions t on t.account_id=a.id group by a.id;grant select on public.account_balances to authenticated,service_role;
create table public.pl_parties(id uuid primary key default gen_random_uuid(),kind text not null check(kind in ('pengirim','penerima')),name text not null check(char_length(trim(name)) between 1 and 120),company text,phone text,address text,city text,notes text,created_by uuid default auth.uid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
grant select,insert,update,delete on public.pl_parties to authenticated;grant all on public.pl_parties to service_role;alter table public.pl_parties enable row level security;
create table public.pl_vessels(id uuid primary key default gen_random_uuid(),name text not null check(char_length(trim(name)) between 1 and 120),operator text,call_sign text,notes text,created_by uuid default auth.uid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
grant select,insert,update,delete on public.pl_vessels to authenticated;grant all on public.pl_vessels to service_role;alter table public.pl_vessels enable row level security;
create table public.pl_ports(id uuid primary key default gen_random_uuid(),name text not null check(char_length(trim(name)) between 1 and 120),city text,code text,created_by uuid default auth.uid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
grant select,insert,update,delete on public.pl_ports to authenticated;grant all on public.pl_ports to service_role;alter table public.pl_ports enable row level security;
create sequence public.pl_number_seq;
create table public.pl_packing_lists(id uuid primary key default gen_random_uuid(),pl_number text not null unique,pl_date date not null default current_date,shipper_id uuid not null references public.pl_parties(id),consignee_id uuid not null references public.pl_parties(id),vessel_id uuid references public.pl_vessels(id),voyage_no text,origin_port_id uuid references public.pl_ports(id),destination_port_id uuid references public.pl_ports(id),container_no text,seal_no text,etd date,eta date,status public.pl_status not null default 'draft',status_changed_at timestamptz not null default now(),status_changed_by uuid default auth.uid(),notes text,total_koli numeric not null default 0,total_weight_kg numeric not null default 0,total_volume_m3 numeric not null default 0,total_value numeric not null default 0,item_count int not null default 0,created_by uuid default auth.uid(),updated_by uuid default auth.uid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
grant select,delete on public.pl_packing_lists to authenticated;grant all on public.pl_packing_lists to service_role;alter table public.pl_packing_lists enable row level security;
create table public.pl_items(id uuid primary key default gen_random_uuid(),packing_list_id uuid not null references public.pl_packing_lists(id) on delete cascade,line_no int not null,name text not null check(char_length(trim(name)) between 1 and 200),qty numeric not null check(qty>0),unit text not null check(unit in ('koli','kardus','karung','peti','pallet')),weight_kg numeric not null default 0 check(weight_kg>=0),length_cm numeric,width_cm numeric,height_cm numeric,volume_m3 numeric not null default 0,value_idr numeric,notes text,condition text not null default 'baik' check(condition in ('baik','rusak_ringan','rusak_berat','basah','kurang')),created_at timestamptz not null default now());
grant select on public.pl_items to authenticated;grant all on public.pl_items to service_role;alter table public.pl_items enable row level security;
create table public.pl_status_history(id uuid primary key default gen_random_uuid(),packing_list_id uuid not null references public.pl_packing_lists(id) on delete cascade,from_status public.pl_status,to_status public.pl_status not null,note text,changed_by uuid,changed_by_name text,changed_at timestamptz not null default now());
grant select on public.pl_status_history to authenticated;grant all on public.pl_status_history to service_role;alter table public.pl_status_history enable row level security;
create table public.pl_activity_logs(id uuid primary key default gen_random_uuid(),packing_list_id uuid,entity text not null,entity_id uuid,action text not null,summary text not null,details jsonb,actor_id uuid,actor_name text,created_at timestamptz not null default now());
grant select on public.pl_activity_logs to authenticated;grant all on public.pl_activity_logs to service_role;alter table public.pl_activity_logs enable row level security;
do $$declare t text;begin foreach t in array array['pl_parties','pl_vessels','pl_ports','pl_packing_lists','pl_items','pl_status_history','pl_activity_logs'] loop execute format('create policy "packing staff read" on public.%I for select to authenticated using(public.is_staff())',t);if t in ('pl_parties','pl_vessels','pl_ports') then execute format('create policy "packing staff insert" on public.%I for insert to authenticated with check(public.is_staff())',t);execute format('create policy "packing staff update" on public.%I for update to authenticated using(public.is_staff()) with check(public.is_staff())',t);end if;if t in ('pl_parties','pl_vessels','pl_ports','pl_packing_lists') then execute format('create policy "super admin delete" on public.%I for delete to authenticated using(public.has_role(auth.uid(),''super_admin''))',t);end if;end loop;end$$;
create index pl_shipper_idx on public.pl_packing_lists(shipper_id);create index pl_consignee_idx on public.pl_packing_lists(consignee_id);create index pl_vessel_idx on public.pl_packing_lists(vessel_id);create index pl_origin_idx on public.pl_packing_lists(origin_port_id);create index pl_destination_idx on public.pl_packing_lists(destination_port_id);create index pl_items_parent_idx on public.pl_items(packing_list_id);create index pl_history_parent_idx on public.pl_status_history(packing_list_id);
alter publication supabase_realtime add table public.transactions,public.bank_accounts,public.audit_logs,public.import_batches,public.pl_packing_lists,public.pl_parties,public.pl_vessels,public.pl_ports,public.pl_activity_logs;